set-variable.value:
@{
            var id = context.Request.Headers.GetValueOrDefault("x-response-request-id", "");
            var raw = context.Request.Headers.GetValueOrDefault("x-response-metrics", "");
            if (!System.Text.RegularExpressions.Regex.IsMatch(id, @"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z")) { return ""; }
            if (raw.Length == 0 || raw.Length > 4096) { return ""; }
            try {
                var metrics = JObject.Parse(raw);
                if (metrics.Count == 0 || metrics.Count > 32) { return ""; }
                foreach (var metric in metrics.Properties()) {
                    if (!System.Text.RegularExpressions.Regex.IsMatch(metric.Name, @"^[a-z][a-z0-9_]{0,63}\z")) { return ""; }
                    if (metric.Value.Type == JTokenType.Null) { continue; }
                    if (metric.Value.Type != JTokenType.Integer && metric.Value.Type != JTokenType.Float) { return ""; }
                    if (metric.Value.Type == JTokenType.Integer) {
                        var number = (long)metric.Value;
                        if (number < -1000000000000000000L || number > 1000000000000000000L) { return ""; }
                    } else {
                        var number = (double)metric.Value;
                        if (double.IsNaN(number) || double.IsInfinity(number) || Math.Abs(number) > 1e18) { return ""; }
                    }
                }
                var canonical = metrics.ToString(Newtonsoft.Json.Formatting.None);
                return canonical.Length <= 4096 ? canonical : "";
            } catch (Exception) { return ""; }
        }

set-header.value:
@{
                    var metrics = JObject.Parse((string)context.Variables["response-metrics"]);
                    var available = 0;
                    foreach (var metric in metrics.Properties()) {
                        if (metric.Value.Type != JTokenType.Null) { available++; }
                    }
                    return available == 0 ? "unavailable" : (available == metrics.Count ? "proxy-reported" : "partial");
                }
